# -*- coding: utf-8 -*-
"""
Second batch of hand-authored specs: the formulas that were still empty skeletons.

Where a statute article is not certain it is left to the lawyer through the
optional field `legal_basis_text` (an empty optional line is dropped from the
paper) instead of being invented.
"""
import copy
from formula_specs import SPECS, spec, F, T, D, A, BOOK, PRACTICE, RENT, MARRIAGE, FAM_P, CRIM, ADMIN

def spec_fam(**kw):
    spec(**{**FAM_P, **kw})


BASIS_FIELD = F('legal_basis_text', 'السند القانوني (المواد)', A, 'اذكر المواد القانونية بعد مراجعتها — يُترك فارغًا إن لم يلزم')
KEEP = '{{legal_basis_text}}'
P = (PRACTICE, 'الأعراف الشائعة للمحاكم المصرية')

