PET = dict(kind='petition', category='طلبات')
def petition(key, ids, title, subject, facts, requests, fields, addressee_hint, basis=None, category='طلبات'):
    spec(key=key, replaces=ids, title=title, subject=subject, kind='petition', category=category,
         facts=facts, basis=basis or [KEEP], requests=requests, addressee_hint=addressee_hint,
         fields=fields + ([BASIS_FIELD] if not basis else []), source=P, review=True)

