civil('c_abuse_litigation', ['formula_217'], 'صيغة دعوى تعويض مدني لإساءة استخدام حق التقاضي', 'دعوى تعويض عن إساءة التقاضي',
 'أقام المعلن إليه ضد الطالب الدعوى رقم {{old_case_no}} لسنة {{old_case_year}} {{old_court}} بغير حق وبسوء نية بقصد الكيد والإضرار بالطالب، وقد قضي فيها برفضها بحكم {{judgment_text}}، وترتب على ذلك أضرار مادية وأدبية للطالب تتمثل في {{damages}}.',
 'ليسمع الحكم بإلزامه بأن يؤدي للطالب مبلغ {{compensation}} جنيهًا تعويضًا عن الأضرار التي لحقت به',
 [F('old_case_no', 'رقم الدعوى الكيدية', T, req=True), F('old_case_year', 'سنتها'), F('old_court', 'المحكمة'), F('judgment_text', 'منطوق الحكم', A), F('damages', 'الأضرار', A, req=True), F('compensation', 'مبلغ التعويض (جنيه)', T, req=True)],
 basis=['ولما كان حق التقاضي مباحًا للكافة ولا مسؤولية على من يستعمله ما لم يثبت انحرافه عن استعماله بقصد الكيد والإضرار بالغير، وكانت المادة 163 من القانون المدني توجب التعويض عن كل خطأ سبب ضررًا للغير، فإن الدعوى الكيدية خطأ يوجب التعويض.'])

civil('c_forgery_original', ['formula_169'], 'صيغة دعوى تزوير أصلية', 'دعوى تزوير أصلية',
 'يحتج المعلن إليه الأول في مواجهة الطالب بمحرر مؤرخ {{doc_date}} هو {{doc_desc}}، منسوب صدوره إلى الطالب أو موقع باسمه، وهو محرر مزور على الطالب إذ {{forgery_proof}}، ويخشى الطالب الاحتجاج به عليه مستقبلًا.',
 'ليسمعا الحكم برد وبطلان المحرر المؤرخ {{doc_date}} المبين بصدر هذه الصحيفة وما يترتب على ذلك من آثار',
 [F('doc_date', 'تاريخ المحرر', D), F('doc_desc', 'وصف المحرر', A, req=True), F('forgery_proof', 'وجه التزوير', A, req=True)],
 basis=['ولما كانت المادة 59 من قانون الإثبات في المواد المدنية والتجارية تنص على أنه يجوز لمن يخشى الاحتجاج عليه بمحرر مزور أن يختصم من بيده المحرر ومن يفيد منه ليسمع الحكم برد وبطلان ذلك المحرر، وتراعى في ذلك القواعد المقررة بالإجراءات المعتادة لرفع الدعوى.'], second_opp=True, opp_two=True)

