spec(key='crim_forgery', replaces=['formula_178', 'formula_177'], category='جنح مباشرة', kind='criminal',
 title='صيغة جنحة مباشرة — تزوير محرر عرفي', subject='جنحة تزوير محرر',
 facts=('بتاريخ {{incident_date}} ارتكب المتهم تزويرًا في {{doc_desc}} بأن {{forgery_way}}، واستعمله بتقديمه إلى {{used_at}} مع علمه بتزويره، مما أضرّ بالمدعي بالحقوق المدنية.'),
 basis=['وهذه الواقعة تشكل جريمة التزوير في محرر عرفي واستعماله المنصوص عليها في المادتين 215 و214 من قانون العقوبات، وجريمة التزوير في المحررات الرسمية إن كان المحرر رسميًا (المادة 211).', KEEP],
 requests='ليسمع الحكم بمعاقبته بالمواد المذكورة',
 fields=[F('incident_date', 'تاريخ الواقعة', D), F('doc_desc', 'المحرر المزور', A, req=True), F('forgery_way', 'طريقة التزوير', A, req=True), F('used_at', 'الجهة المستعمل أمامها'), BASIS_FIELD], source=P, review=True)

spec(key='crim_blank_paper', replaces=['formula_183'], category='جنح مباشرة', kind='criminal',
 title='صيغة جنحة مباشرة — خيانة الائتمان في ورقة موقعة على بياض', subject='جنحة خيانة ائتمان (ورقة على بياض)',
 facts=('سلّم المدعي بالحقوق المدنية للمتهم ورقة ممضاة منه على بياض بتاريخ {{handed_date}} على سبيل الائتمان لغرض {{purpose}}، وقد خان المتهم الأمانة وكتب في البياض {{written_text}}، واستعمل الورقة {{misuse}}، إضرارًا بالمدعي.'),
 basis=['وهذه الواقعة تشكل الجريمة المنصوص عليها في المادة 340 من قانون العقوبات التي تعاقب كل من ائتمن على ورقة ممضاة أو مختومة على بياض فخان الأمانة وكتب في البياض سند دين أو مخالصة أو غير ذلك إضرارًا بصاحب الإمضاء.'],
 requests='ليسمع الحكم بمعاقبته بالمادة 340 من قانون العقوبات',
 fields=[F('handed_date', 'تاريخ تسليم الورقة', D), F('purpose', 'غرض التسليم'), F('written_text', 'ما كُتب فوق التوقيع', A, req=True), F('misuse', 'وجه الاستعمال')], source=P, review=True)

spec(key='crim_female_assault', replaces=['formula_179'], category='جنح مباشرة', kind='criminal', female=True,
 title='صيغة جنحة مباشرة — تعرض لأنثى على وجه يخدش حياءها', subject='جنحة تعرض لأنثى',
 facts=('بتاريخ {{incident_date}} وفي {{incident_place}} تعرض المتهم للمدعية بالحقوق المدنية بـ{{act}} على وجه يخدش حياءها، في حضور {{witnesses}}، وقد حرّرت عن ذلك المحضر رقم {{report_no}} لسنة {{report_year}}.'),
 basis=['وهذه الواقعة تشكل الجريمة المنصوص عليها في المادة 306 مكررًا (أ) من قانون العقوبات التي تعاقب كل من تعرض للغير في طريق عام أو مكان مطروق بإتيان أمور أو إيحاءات أو تلميحات جنسية أو إباحية بالإشارة أو بالقول أو بالفعل، وفي المادة 306 مكررًا (ب) إن توافرت ظروفها.', KEEP],
 requests='ليسمع الحكم بمعاقبته بالمواد المذكورة',
 fields=[F('incident_date', 'تاريخ الواقعة', D), F('incident_place', 'مكانها'), F('act', 'الفعل المنسوب للمتهم', A, req=True), F('witnesses', 'الشهود'), F('report_no', 'رقم المحضر'), F('report_year', 'سنته'), BASIS_FIELD], source=P, review=True)

# ═══════════════ القضاء الإداري ═══════════════
def admin_claim(key, ids, title, subject, benefit, extra=None):
    spec(key=key, replaces=ids, title=title, subject=subject, **ADMIN,
         facts=('يعمل الطالب بوظيفة {{job}} لدى {{authority}} منذ {{since}}. وقد صدر {{legal_source}} متضمنًا استحقاق ' + benefit + ' لمن تتوافر فيه الشروط، وتتوافر هذه الشروط في الطالب إذ {{conditions}}. وقد تقدم بطلب صرفه فامتنعت الجهة الإدارية / رفضت بتاريخ {{refusal_date}}، وتظلم من ذلك بتاريخ {{grievance_date}} ولم يجب.'),
         basis=['ولما كان المقرر أن الحقوق الوظيفية المقررة بنص قانوني أو لائحي تستحق لكل من تتوافر فيه شروط استحقاقها، وكان امتناع الجهة الإدارية عن صرفها قرارًا سلبيًا مخالفًا للقانون، تختص محاكم مجلس الدولة بالفصل في الطعن عليه عملًا بالمادة 10 من القانون رقم 47 لسنة 1972.', KEEP],
         requests='ليسمع الحكم بأحقيته في صرف ' + benefit + ' اعتبارًا من {{from_date}} وما يترتب على ذلك من آثار وفروق مالية مع الفوائد القانونية',
         fields=[F('job', 'وظيفة الطالب', T, req=True), F('authority', 'جهة العمل', T, req=True), F('since', 'تاريخ التعيين', D), F('legal_source', 'القرار/اللائحة المقررة للحق', T, req=True),
                 F('conditions', 'توافر الشروط في الطالب', A, req=True), F('from_date', 'من تاريخ', D, req=True), F('refusal_date', 'تاريخ الرفض/الامتناع', D), F('grievance_date', 'تاريخ التظلم', D), BASIS_FIELD] + (extra or []),
         source=P, review=True)

admin_claim('admin_risk', ['formula_147', 'formula_150'], 'صيغة دعوى صرف بدل مخاطر / بدل عدوى', 'دعوى صرف بدل مخاطر أو عدوى', 'بدل المخاطر / بدل العدوى')
admin_claim('admin_leave', ['formula_151', 'formula_154'], 'صيغة دعوى صرف مقابل رصيد الإجازات', 'دعوى صرف مقابل رصيد إجازات', 'مقابل رصيد الإجازات السنوية غير المستنفدة')
